export function ukraineReparationsSvg(lang, kind, mobile = false) {
  if (!['fr', 'en'].includes(lang) || !UKRAINE_REPARATIONS_KINDS.includes(kind) || typeof mobile !== 'boolean') throw new TypeError('Invalid Ukraine reparations figure variant');
  return snippets[`${kind}-${lang}-${mobile ? 'mobile' : 'desktop'}`];
}
